import{c as t,Q as a,j as r,m as o}from"./chunks/framework.BPKcPtvA.js";const p=JSON.parse('{"title":"FAQ - Troubleshooting Flagged Addresses & Failed Withdrawals","description":"Frequently asked questions about Hyperliquid flagged addresses: Action Blocked error, withdrawal limits, safety of private keys, and HYPE staking cooldown period.","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://hyperliquidrecoverybot.github.io/en/faq"}],["link",{"rel":"alternate","hreflang":"en","href":"https://hyperliquidrecoverybot.github.io/en/faq"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://hyperliquidrecoverybot.github.io/zh/faq"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://hyperliquidrecoverybot.github.io/en/faq"}],["meta",{"name":"keywords","content":"Hyperliquid FAQ, Action Blocked help, bypass high risk restriction, withdraw HYPE, recover flagged address"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"FAQ - Troubleshooting Flagged Addresses & Failed Withdrawals"}],["meta",{"property":"og:description","content":"Frequently asked questions about Hyperliquid flagged addresses: Action Blocked error, withdrawal limits, safety of private keys, and HYPE staking cooldown period."}],["meta",{"property":"og:url","content":"https://hyperliquidrecoverybot.github.io/en/faq"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"FAQ - Troubleshooting Flagged Addresses & Failed Withdrawals"}],["meta",{"name":"twitter:description","content":"Frequently asked questions about Hyperliquid flagged addresses: Action Blocked error, withdrawal limits, safety of private keys, and HYPE staking cooldown period."}]]},"headers":[],"relativePath":"en/faq.md","filePath":"en/faq.md","lastUpdated":null}'),i={name:"en/faq.md"};function s(l,e,n,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="hyperliquid-recovery-faq-flagged-address-troubleshooting" tabindex="-1">Hyperliquid Recovery FAQ: Flagged Address Troubleshooting <a class="header-anchor" href="#hyperliquid-recovery-faq-flagged-address-troubleshooting" aria-label="Permalink to &quot;Hyperliquid Recovery FAQ: Flagged Address Troubleshooting&quot;">​</a></h1><p>This troubleshooting guide provides technical solutions for extracting assets from a flagged Hyperliquid address or restricted account.</p><h2 id="🤖-bot-basic-questions" tabindex="-1">🤖 Bot Basic Questions <a class="header-anchor" href="#🤖-bot-basic-questions" aria-label="Permalink to &quot;🤖 Bot Basic Questions&quot;">​</a></h2><h3 id="q-what-is-hyperliquid-recovery-bot" tabindex="-1">Q: What is Hyperliquid Recovery Bot? <a class="header-anchor" href="#q-what-is-hyperliquid-recovery-bot" aria-label="Permalink to &quot;Q: What is Hyperliquid Recovery Bot?&quot;">​</a></h3><p><strong>A:</strong> Hyperliquid Recovery Bot is a professional Telegram bot designed specifically for Hyperliquid ecosystem users to help users safely recover digital assets from addresses flagged as high-risk.</p><h3 id="q-is-the-bot-free-to-use" tabindex="-1">Q: Is the bot free to use? <a class="header-anchor" href="#q-is-the-bot-free-to-use" aria-label="Permalink to &quot;Q: Is the bot free to use?&quot;">​</a></h3><p><strong>A:</strong> Address detection is completely FREE. Asset recovery services charge:</p><ul><li><strong>Service Fee</strong>: 0.5% of total asset value (minimum 1 USDC)</li><li><strong>Withdrawal Fees</strong>: 2 USDC (Hyperliquid platform)</li><li><strong>Example</strong>: Recover $1,000 → Pay $7 → Get $993</li></ul><h3 id="q-how-to-confirm-this-is-the-official-bot" tabindex="-1">Q: How to confirm this is the official bot? <a class="header-anchor" href="#q-how-to-confirm-this-is-the-official-bot" aria-label="Permalink to &quot;Q: How to confirm this is the official bot?&quot;">​</a></h3><p><strong>A:</strong> Please ensure you access the bot using the official link:</p><ul><li><strong>Official Address</strong>: <a href="https://t.me/HyperliquidRecoveryBot?start=vsAPDn_gitbook" target="_blank" rel="noreferrer">https://t.me/HyperliquidRecoveryBot</a></li><li><strong>Username</strong>: <a href="https://t.me/HyperliquidRecoveryBot?start=vsAPDn_gitbook" target="_blank" rel="noreferrer">@HyperliquidRecoveryBot</a></li><li><strong>Verification</strong>: Check the bot&#39;s function menu and interface features</li></ul><h3 id="q-what-languages-does-the-bot-support" tabindex="-1">Q: What languages does the bot support? <a class="header-anchor" href="#q-what-languages-does-the-bot-support" aria-label="Permalink to &quot;Q: What languages does the bot support?&quot;">​</a></h3><p><strong>A:</strong> Currently supports:</p><ul><li><strong>Chinese</strong>: Complete Simplified Chinese support</li><li><strong>English</strong>: Full English language support</li></ul><h3 id="q-what-are-the-bot-s-operating-hours" tabindex="-1">Q: What are the bot&#39;s operating hours? <a class="header-anchor" href="#q-what-are-the-bot-s-operating-hours" aria-label="Permalink to &quot;Q: What are the bot&#39;s operating hours?&quot;">​</a></h3><p><strong>A:</strong> The bot runs continuously and can be used at any time. However, it is recommended to perform important operations when network conditions are good.</p><h2 id="🔍-address-detection-questions" tabindex="-1">🔍 Address Detection Questions <a class="header-anchor" href="#🔍-address-detection-questions" aria-label="Permalink to &quot;🔍 Address Detection Questions&quot;">​</a></h2><h3 id="q-what-address-formats-are-supported" tabindex="-1">Q: What address formats are supported? <a class="header-anchor" href="#q-what-address-formats-are-supported" aria-label="Permalink to &quot;Q: What address formats are supported?&quot;">​</a></h3><p><strong>A:</strong> Supports standard Hyperliquid address formats:</p><ul><li><strong>Length</strong>: 42 characters (including 0x prefix)</li><li><strong>Format</strong>: 0x + 40 hexadecimal characters</li><li><strong>Example</strong>: 0x1234567890123456789012345678901234567890</li></ul><h3 id="q-how-long-does-detection-take" tabindex="-1">Q: How long does detection take? <a class="header-anchor" href="#q-how-long-does-detection-take" aria-label="Permalink to &quot;Q: How long does detection take?&quot;">​</a></h3><p><strong>A:</strong> Usually completed within a few seconds to a few minutes, depending on:</p><ul><li>Network conditions</li><li>Hyperliquid API response speed</li><li>Number and complexity of assets in the address</li></ul><h3 id="q-is-the-detected-asset-information-accurate" tabindex="-1">Q: Is the detected asset information accurate? <a class="header-anchor" href="#q-is-the-detected-asset-information-accurate" aria-label="Permalink to &quot;Q: Is the detected asset information accurate?&quot;">​</a></h3><p><strong>A:</strong> Yes, the bot uses Hyperliquid official API to get real-time data, which is accurate and reliable. However, please note:</p><ul><li>Price information may have 1-2 minutes delay</li><li>Some new tokens may temporarily have no price information</li><li>Network congestion may affect data updates</li></ul><h3 id="q-why-do-some-assets-not-display-prices" tabindex="-1">Q: Why do some assets not display prices? <a class="header-anchor" href="#q-why-do-some-assets-not-display-prices" aria-label="Permalink to &quot;Q: Why do some assets not display prices?&quot;">​</a></h3><p><strong>A:</strong> Possible reasons:</p><ul><li>Newly listed tokens have no price data yet</li><li>Low liquidity tokens</li><li>Price API temporarily unavailable</li><li>Token has been delisted or stopped trading</li></ul><h3 id="q-can-multiple-addresses-be-detected" tabindex="-1">Q: Can multiple addresses be detected? <a class="header-anchor" href="#q-can-multiple-addresses-be-detected" aria-label="Permalink to &quot;Q: Can multiple addresses be detected?&quot;">​</a></h3><p><strong>A:</strong> Each detection run currently processes one address. You can repeat detection for different addresses.</p><h3 id="q-how-long-is-detection-history-saved" tabindex="-1">Q: How long is detection history saved? <a class="header-anchor" href="#q-how-long-is-detection-history-saved" aria-label="Permalink to &quot;Q: How long is detection history saved?&quot;">​</a></h3><p><strong>A:</strong> This public guide does not treat detection history as a long-term record. Please use the current result page as your main reference.</p><h2 id="🛠️-asset-recovery-questions" tabindex="-1">🛠️ Asset Recovery Questions <a class="header-anchor" href="#🛠️-asset-recovery-questions" aria-label="Permalink to &quot;🛠️ Asset Recovery Questions&quot;">​</a></h2><h3 id="q-what-asset-types-can-be-recovered" tabindex="-1">Q: What asset types can be recovered? <a class="header-anchor" href="#q-what-asset-types-can-be-recovered" aria-label="Permalink to &quot;Q: What asset types can be recovered?&quot;">​</a></h3><p><strong>A:</strong> The bot can recover 4 types of assets:</p><ul><li>✅ <strong>Spot Assets</strong>: USDC, ETH, BTC, and other tokens</li><li>✅ <strong>Perpetual Contracts</strong>: Long/short positions</li><li>✅ <strong>Vault Assets</strong>: Assets deposited in vaults (if not locked)</li><li>✅ <strong>Staked Assets</strong>: HYPE tokens staked to validators (requires waiting period)</li></ul><h3 id="q-when-is-asset-recovery-needed" tabindex="-1">Q: When is asset recovery needed? <a class="header-anchor" href="#q-when-is-asset-recovery-needed" aria-label="Permalink to &quot;Q: When is asset recovery needed?&quot;">​</a></h3><p><strong>A:</strong> When your address is flagged as high-risk and:</p><ul><li>The frontend can connect the address, but typically you are unable to perform Hyperliquid L1 native asset operations (like transfers, trades, or withdrawals).</li><li>The frontend may show a warning overlay with system responses such as:</li></ul><div class="language-log vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">log</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Action blocked: Address flagged for suspicious activity. Your address has been flagged as high risk by a third-party screening tool. This frontend interface does not support connection to the Hyperliquid blockchain by high risk addresses.</span></span></code></pre></div><ul><li>A red warning overlay appears and operation buttons are disabled.</li><li>Cannot perform normal trading operations.</li><li>Assets may be restricted in frontend operations.</li></ul><h3 id="q-how-long-does-the-recovery-process-take" tabindex="-1">Q: How long does the recovery process take? <a class="header-anchor" href="#q-how-long-does-the-recovery-process-take" aria-label="Permalink to &quot;Q: How long does the recovery process take?&quot;">​</a></h3><p><strong>A:</strong> Spot and perpetual assets are usually recovered quickly. For staked assets, recovery usually takes 2-3 runs depending on current state:</p><ul><li><strong>Optimized path (2 runs)</strong>: when undelegated balance already exists</li><li><strong>Standard path (3 runs)</strong>: when only delegated balance exists (typically 1 day + 7 days windows)</li></ul><h3 id="q-can-the-recovery-process-be-cancelled" tabindex="-1">Q: Can the recovery process be cancelled? <a class="header-anchor" href="#q-can-the-recovery-process-be-cancelled" aria-label="Permalink to &quot;Q: Can the recovery process be cancelled?&quot;">​</a></h3><p><strong>A:</strong> Once confirmed to start recovery operation, it cannot be cancelled. Therefore, please carefully check all information before confirmation.</p><h3 id="q-is-the-private-key-secure" tabindex="-1">Q: Is the private key secure? <a class="header-anchor" href="#q-is-the-private-key-secure" aria-label="Permalink to &quot;Q: Is the private key secure?&quot;">​</a></h3><p><strong>A:</strong> Follow these basic rules:</p><ul><li>Enter credentials only in the bot&#39;s official recovery flow</li><li>Never send private keys or mnemonics to any person, group, form, or external website</li><li>Do not screenshot, forward, or paste credentials into chat windows</li><li>If you cannot confirm the bot entry is official, stop and verify first</li></ul><h3 id="q-what-if-i-have-staked-hype-tokens" tabindex="-1">Q: What if I have staked HYPE tokens? <a class="header-anchor" href="#q-what-if-i-have-staked-hype-tokens" aria-label="Permalink to &quot;Q: What if I have staked HYPE tokens?&quot;">​</a></h3><p><strong>A:</strong> The bot handles staking states automatically and tells you when to rerun:</p><ul><li>It may complete in 2 runs if part of the balance is already ready for the next stage</li><li>Or require 3 runs if the balance must first pass through the full unstake waiting flow</li></ul><h3 id="q-what-if-my-vault-assets-are-locked" tabindex="-1">Q: What if my vault assets are locked? <a class="header-anchor" href="#q-what-if-my-vault-assets-are-locked" aria-label="Permalink to &quot;Q: What if my vault assets are locked?&quot;">​</a></h3><p><strong>A:</strong> The bot will skip locked vault assets:</p><ul><li>Wait for the lock period to end</li><li>Then run recovery again to withdraw them</li></ul><h3 id="q-can-i-specify-withdrawal-to-a-specific-address" tabindex="-1">Q: Can I specify withdrawal to a specific address? <a class="header-anchor" href="#q-can-i-specify-withdrawal-to-a-specific-address" aria-label="Permalink to &quot;Q: Can I specify withdrawal to a specific address?&quot;">​</a></h3><p><strong>A:</strong> No. Recovery does not require destination input. Funds are withdrawn to the Arbitrum address corresponding to the source address.</p><h3 id="q-what-to-do-if-recovery-fails" tabindex="-1">Q: What to do if recovery fails? <a class="header-anchor" href="#q-what-to-do-if-recovery-fails" aria-label="Permalink to &quot;Q: What to do if recovery fails?&quot;">​</a></h3><p><strong>A:</strong> First check which task-level outcome appears on the result page:</p><ul><li><code>failed</code>: this run was interrupted by a fatal error; review the cause before retrying</li><li><code>partial</code>: this run recovered some assets, but remaining assets still need attention</li><li><code>waiting_to_rerun</code>: this run progressed correctly, but you must wait for protocol windows to end before the next run</li></ul><p>If the final outcome is truly <code>failed</code>, the bot will automatically retry on network failures. If it continues to fail:</p><ol><li>Check your internet connection</li><li>Verify private key is correct</li><li>Check error message</li><li>Contact support if needed</li></ol><h2 id="💰-fee-related-questions" tabindex="-1">💰 Fee Related Questions <a class="header-anchor" href="#💰-fee-related-questions" aria-label="Permalink to &quot;💰 Fee Related Questions&quot;">​</a></h2><h3 id="q-how-much-does-recovery-cost" tabindex="-1">Q: How much does recovery cost? <a class="header-anchor" href="#q-how-much-does-recovery-cost" aria-label="Permalink to &quot;Q: How much does recovery cost?&quot;">​</a></h3><p><strong>A:</strong> Total cost = Service Fee + Withdrawal Fees</p><ul><li><strong>Service Fee</strong>: 0.5% of total asset value (minimum 1 USDC)</li><li><strong>Withdrawal Fees</strong>: 2 USDC (Hyperliquid platform charges)</li></ul><p><strong>Examples</strong>:</p><table tabindex="0"><thead><tr><th>Your Assets</th><th>Service Fee</th><th>Withdrawal Fees</th><th>Total Cost</th><th>You Receive</th></tr></thead><tbody><tr><td>$100</td><td>$1</td><td>$2</td><td>$3</td><td>$97</td></tr><tr><td>$1,000</td><td>$5</td><td>$2</td><td>$7</td><td>$993</td></tr><tr><td>$10,000</td><td>$50</td><td>$2</td><td>$52</td><td>$9,948</td></tr></tbody></table><h3 id="q-what-does-the-service-fee-include" tabindex="-1">Q: What does the service fee include? <a class="header-anchor" href="#q-what-does-the-service-fee-include" aria-label="Permalink to &quot;Q: What does the service fee include?&quot;">​</a></h3><p><strong>A:</strong> Service fee includes:</p><ul><li>All asset conversions (ETH, BTC, etc. → USDC)</li><li>All account transfers (Spot → Perpetual)</li><li>Recovery orchestration and execution service</li><li>Technical support</li></ul><p><strong>Note:</strong> Hyperliquid withdrawal fees are billed separately under <code>Withdrawal Fees</code>.</p><h3 id="q-when-is-the-service-fee-charged" tabindex="-1">Q: When is the service fee charged? <a class="header-anchor" href="#q-when-is-the-service-fee-charged" aria-label="Permalink to &quot;Q: When is the service fee charged?&quot;">​</a></h3><p><strong>A:</strong> Service fee is processed during the service-fee collection stage in the recovery pipeline. If execution does not reach fee collection, no service fee is charged.</p><h3 id="q-why-are-there-withdrawal-fees" tabindex="-1">Q: Why are there withdrawal fees? <a class="header-anchor" href="#q-why-are-there-withdrawal-fees" aria-label="Permalink to &quot;Q: Why are there withdrawal fees?&quot;">​</a></h3><p><strong>A:</strong> Hyperliquid platform charges 1 USDC per withdrawal. The bot makes 2 withdrawals:</p><ol><li>First withdrawal: Collect service fee (1 USDC)</li><li>Second withdrawal: Send your assets (1 USDC) Total: 2 USDC withdrawal fees</li></ol><h2 id="🔒-security-related-questions" tabindex="-1">🔒 Security Related Questions <a class="header-anchor" href="#🔒-security-related-questions" aria-label="Permalink to &quot;🔒 Security Related Questions&quot;">​</a></h2><h3 id="q-how-to-ensure-operation-security" tabindex="-1">Q: How to ensure operation security? <a class="header-anchor" href="#q-how-to-ensure-operation-security" aria-label="Permalink to &quot;Q: How to ensure operation security?&quot;">​</a></h3><p><strong>A:</strong> Please follow these security recommendations:</p><ul><li>Operate in secure devices and network environments</li><li>Do not enter private keys in public places</li><li>Carefully verify each operation step</li><li>If you use a shared device, log out and close related chats after use</li></ul><h3 id="q-will-private-keys-be-saved" tabindex="-1">Q: Will private keys be saved? <a class="header-anchor" href="#q-will-private-keys-be-saved" aria-label="Permalink to &quot;Q: Will private keys be saved?&quot;">​</a></h3><p><strong>A:</strong> This user guide focuses on what you should do as a user: only enter credentials in the bot&#39;s official recovery flow, never provide them to any person or external page, and verify results with transaction hashes and on-chain records.</p><h3 id="q-how-to-prevent-fraud" tabindex="-1">Q: How to prevent fraud? <a class="header-anchor" href="#q-how-to-prevent-fraud" aria-label="Permalink to &quot;Q: How to prevent fraud?&quot;">​</a></h3><p><strong>A:</strong> Please note:</p><ul><li>Only use the official bot <a href="https://t.me/HyperliquidRecoveryBot?start=vsAPDn_gitbook" target="_blank" rel="noreferrer">@HyperliquidRecoveryBot</a></li><li>Do not enter private keys elsewhere</li><li>Outside the bot&#39;s official recovery flow, no support staff, private chat, or group will ask for your private key or mnemonic</li><li>Be wary of false promises and unreasonable profit guarantees</li></ul><h3 id="q-what-to-do-if-suspicious-activity-is-found" tabindex="-1">Q: What to do if suspicious activity is found? <a class="header-anchor" href="#q-what-to-do-if-suspicious-activity-is-found" aria-label="Permalink to &quot;Q: What to do if suspicious activity is found?&quot;">​</a></h3><p><strong>A:</strong> If any suspicious activity is found:</p><ol><li>Stop operation immediately</li><li>Screenshot and save evidence (excluding sensitive information)</li></ol><h2 id="🔧-technical-questions" tabindex="-1">🔧 Technical Questions <a class="header-anchor" href="#🔧-technical-questions" aria-label="Permalink to &quot;🔧 Technical Questions&quot;">​</a></h2><h3 id="q-why-does-address-validation-fail" tabindex="-1">Q: Why does address validation fail? <a class="header-anchor" href="#q-why-does-address-validation-fail" aria-label="Permalink to &quot;Q: Why does address validation fail?&quot;">​</a></h3><p><strong>A:</strong> Possible reasons:</p><ul><li>Incorrect address format (missing 0x prefix or wrong length)</li><li>Contains invalid characters</li><li>Extra spaces or characters included during copy-paste</li><li>Not a valid Hyperliquid (EVM) address format</li></ul><h3 id="q-why-does-private-key-validation-fail" tabindex="-1">Q: Why does private key validation fail? <a class="header-anchor" href="#q-why-does-private-key-validation-fail" aria-label="Permalink to &quot;Q: Why does private key validation fail?&quot;">​</a></h3><p><strong>A:</strong> Possible reasons:</p><ul><li>Private key format does not match current input requirements (including optional prefix/length mismatch)</li><li>Incorrect private key length (should be 64 hexadecimal characters)</li><li>Private key does not match address</li><li>Extra characters included during input</li></ul><h3 id="q-how-to-handle-network-errors" tabindex="-1">Q: How to handle network errors? <a class="header-anchor" href="#q-how-to-handle-network-errors" aria-label="Permalink to &quot;Q: How to handle network errors?&quot;">​</a></h3><p><strong>A:</strong> When encountering network errors:</p><ol><li>Check if network connection is stable</li><li>Try switching to a more stable network</li><li>Wait a few minutes and retry</li></ol><h3 id="q-what-to-do-if-api-calls-fail" tabindex="-1">Q: What to do if API calls fail? <a class="header-anchor" href="#q-what-to-do-if-api-calls-fail" aria-label="Permalink to &quot;Q: What to do if API calls fail?&quot;">​</a></h3><p><strong>A:</strong> API call failures may be due to:</p><ul><li>Hyperliquid API temporarily unavailable</li><li>Network connection issues</li><li>Request frequency too high</li><li>Recommend retrying later</li></ul><h2 id="📱-user-experience-questions" tabindex="-1">📱 User Experience Questions <a class="header-anchor" href="#📱-user-experience-questions" aria-label="Permalink to &quot;📱 User Experience Questions&quot;">​</a></h2><h3 id="q-can-it-be-used-on-mobile-phones" tabindex="-1">Q: Can it be used on mobile phones? <a class="header-anchor" href="#q-can-it-be-used-on-mobile-phones" aria-label="Permalink to &quot;Q: Can it be used on mobile phones?&quot;">​</a></h3><p><strong>A:</strong> Yes, the bot fully supports mobile use. Recommendations:</p><ul><li>Use the latest version of Telegram app</li><li>Ensure stable mobile network connection</li><li>Operate in secure environment</li></ul><h3 id="q-what-to-do-if-interface-display-is-abnormal" tabindex="-1">Q: What to do if interface display is abnormal? <a class="header-anchor" href="#q-what-to-do-if-interface-display-is-abnormal" aria-label="Permalink to &quot;Q: What to do if interface display is abnormal?&quot;">​</a></h3><p><strong>A:</strong> If interface display is abnormal:</p><ol><li>Try restarting Telegram app</li><li>Send /start command to reinitialize</li><li>Check if Telegram app is the latest version</li></ol><h3 id="q-what-to-do-if-operation-response-is-slow" tabindex="-1">Q: What to do if operation response is slow? <a class="header-anchor" href="#q-what-to-do-if-operation-response-is-slow" aria-label="Permalink to &quot;Q: What to do if operation response is slow?&quot;">​</a></h3><p><strong>A:</strong> Slow operation response may be due to:</p><ul><li>Unstable network connection</li><li>High Telegram server load</li><li>Slow Hyperliquid API response</li><li>Recommend operating when network conditions are good</li></ul><h2 id="🆘-emergency-situations" tabindex="-1">🆘 Emergency Situations <a class="header-anchor" href="#🆘-emergency-situations" aria-label="Permalink to &quot;🆘 Emergency Situations&quot;">​</a></h2><h3 id="q-what-to-do-if-errors-occur-during-recovery-process" tabindex="-1">Q: What to do if errors occur during recovery process? <a class="header-anchor" href="#q-what-to-do-if-errors-occur-during-recovery-process" aria-label="Permalink to &quot;Q: What to do if errors occur during recovery process?&quot;">​</a></h3><p><strong>A:</strong> If errors occur during recovery process:</p><ol><li>Don&#39;t panic, record error information</li><li>Check if network connection is normal</li><li>Check whether the result page shows <code>partial</code> or <code>waiting_to_rerun</code>, since these do not always mean the run failed</li></ol><h3 id="q-what-to-do-if-assets-don-t-arrive-on-arbitrum" tabindex="-1">Q: What to do if assets don&#39;t arrive on Arbitrum? <a class="header-anchor" href="#q-what-to-do-if-assets-don-t-arrive-on-arbitrum" aria-label="Permalink to &quot;Q: What to do if assets don&#39;t arrive on Arbitrum?&quot;">​</a></h3><p><strong>A:</strong> If assets do not arrive on the source address on Arbitrum:</p><ol><li>Check transaction hash status in blockchain explorer</li><li>Confirm the source address is correct and can receive on Arbitrum</li><li>Wait for Hyperliquid processing and additional confirmations (arrival may take several to more than ten minutes)</li></ol><h2 id="📊-other-questions" tabindex="-1">📊 Other Questions <a class="header-anchor" href="#📊-other-questions" aria-label="Permalink to &quot;📊 Other Questions&quot;">​</a></h2><h3 id="q-can-i-view-historical-operation-records" tabindex="-1">Q: Can I view historical operation records? <a class="header-anchor" href="#q-can-i-view-historical-operation-records" aria-label="Permalink to &quot;Q: Can I view historical operation records?&quot;">​</a></h3><p><strong>A:</strong> The public workflow should not currently be treated as providing a complete recovery-task history viewer. Use the result summary and transaction hashes as the primary audit trail.</p><h3 id="q-will-the-bot-be-updated-regularly" tabindex="-1">Q: Will the bot be updated regularly? <a class="header-anchor" href="#q-will-the-bot-be-updated-regularly" aria-label="Permalink to &quot;Q: Will the bot be updated regularly?&quot;">​</a></h3><p><strong>A:</strong> Yes, we will update the bot regularly:</p><ul><li>Fix known issues</li><li>Add new features</li><li>Improve user experience</li><li>Enhance security</li></ul><h3 id="q-are-there-tutorials-or-videos-available" tabindex="-1">Q: Are there tutorials or videos available? <a class="header-anchor" href="#q-are-there-tutorials-or-videos-available" aria-label="Permalink to &quot;Q: Are there tutorials or videos available?&quot;">​</a></h3><p><strong>A:</strong> Currently provides:</p><ul><li>Detailed text tutorials</li><li>Illustrated user guides</li><li>Frequently asked questions</li><li>Video tutorials are in production</li><li>Check this documentation for the latest guides and updates</li></ul><hr><h2 id="💬-have-other-questions" tabindex="-1">💬 Have Other Questions? <a class="header-anchor" href="#💬-have-other-questions" aria-label="Permalink to &quot;💬 Have Other Questions?&quot;">​</a></h2><p>If your question is not answered here, please:</p><ol><li><p><strong>View Other Documentation</strong>:</p><ul><li><a href="./quick-start">Quick Start</a></li><li><a href="./bot-usage">Bot Usage Guide</a></li></ul></li><li><p><strong>Use In-Bot Feedback</strong>:</p><ul><li>Submit your issue with non-sensitive details</li><li>Include error messages and tx hash when available</li></ul></li><li><p><strong>Community Support</strong>:</p><ul><li>Join user discussion groups</li><li>View community discussions</li><li>Share usage experiences</li></ul></li></ol><p><strong>Remember</strong>: We are committed to providing you with the best service and support!</p>',134)])])}const f=t(i,[["render",s]]);export{p as __pageData,f as default};
